from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/api', methods=['GET'])
def api():
    # Получаем параметр полезной нагрузки из URL-адреса
    payload = request.args.get('payload', '{}')

    # Загружаем полезную нагрузку в словарь
    try:
        data = eval(payload)  # Используем eval для простоты, но в продакшене лучше использовать json.loads
    except:
        data = {}

    # Возвращаем значение имени из словаря, если найдено, иначе "Гость"
    name = data.get('name', 'Гость')

    return jsonify({'name': name})

if __name__ == '__main__':
    app.run(debug=True)

